sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float shape;
half4 main(float2 coord) {
    float2 h = size * 0.5;
    float2 p = (coord - h) / h;
    float strength = amount;
    if (shape > 0.5 && strength < 0.0) p = p.yx;
    float a = (shape > 0.5 ? abs(strength) : strength) * 0.5;
    float squeeze = 1.0 - a * (1.0 - p.y * p.y);
    if (squeeze <= 0.0001) return half4(0.0);
    float2 q = float2(p.x / squeeze, p.y / (1.0 + 0.3 * abs(strength)));
    if (shape > 0.5 && strength < 0.0) q = q.yx;
    return image.eval(h + q * h);
}
